 13→
 14→// isolatedConfigDir creates a temp directory that mirrors ~/.claude via
 15→// symlinks but omits CLAUDE.md and skills/ so that test runs don't inherit
 16→// the operator's personal instructions or custom skills.
 17→func isolatedConfigDir() (string, error) {
 18→	home, err := os.UserHomeDir()
 19→	if err != nil {
 20→		return "", fmt.Errorf("get home dir: %w", err)
 21→	}
 22→	src := filepath.Join(home, ".claude")
 23→
 24→	dst, err := os.MkdirTemp("", "claude-config-*")
 25→	if err != nil {
 26→		return "", err
 27→	}
 28→
 29→	entries, err := os.ReadDir(src)
 30→	if err != nil {
 31→		return dst, fmt.Errorf("read %s: %w", src, err)
 32→	}
 33→
 34→	skip := map[string]bool{"CLAUDE.md": true, "skills": true}
 35→	for _, e := range entries {
 36→		if skip[e.Name()] {
 37→			continue
 38→		}
 39→		_ = os.Symlink(filepath.Join(src, e.Name()), filepath.Join(dst, e.Name()))
 40→	}
 41→	return dst, nil
 42→}
 43→
 44→// cleanEnv returns os.Environ() with CLAUDECODE removed so that
 45→// Claude Code doesn't refuse to start inside this test runner.
 46→func cleanEnv() []string {
 47→	var env []string
 48→	for _, e := range os.Environ() {
 49→		if !strings.HasPrefix(e, "CLAUDECODE=") {
 50→			env = append(env, e)
 51→		}
 52→	}
 53→	return env
 54→}
 55→
 56→func init() {
 57→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "claude-code" {
 58→		return
 59→	}
 60→	Register(&Claude{})
 61→}
 62→
 63→type Claude struct{}
 64→
 65→func (c *Claude) Name() string             { return "claude-code" }
 66→func (c *Claude) EntireAgent() string      { return "claude-code" }
 67→func (c *Claude) PromptPattern() string    { return `❯` }
 68→func (c *Claude) TimeoutMultiplier() float64 { return 1.0 }
 69→
 70→func (c *Claude) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 71→	cfg := &runConfig{Model: "haiku"}
 72→	for _, o := range opts {
 73→		o(cfg)
 74→	}
 75→
 76→	configDir, err := isolatedConfigDir()
 77→	if err != nil {
 78→		return Output{}, fmt.Errorf("create isolated config dir: %w", err)
 79→	}
 80→	defer os.RemoveAll(configDir)
 81→
 82→	args := []string{"-p", prompt, "--model", cfg.Model, "--dangerously-skip-permissions"}
 83→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--dangerously-skip-permissions"}
 84→	cmd := exec.CommandContext(ctx, "claude", args...)
 85→	cmd.Dir = dir
 86→	cmd.Stdin = nil
 87→	cmd.Env = append(cleanEnv(), "ACCESSIBLE=1", "ENTIRE_TEST_TTY=0", "CLAUDE_CONFIG_DIR="+configDir)
 88→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
 89→	cmd.Cancel = func() error {
 90→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
 91→	}
 92→	cmd.WaitDelay = 5 * time.Second
 93→
 94→	var stdout, stderr strings.Builder
 95→	cmd.Stdout = &stdout
 96→	cmd.Stderr = &stderr
 97→
 98→	err = cmd.Run()
 99→	exitCode := 0
100→	if exitErr, ok := err.(*exec.ExitError); ok {
101→		exitCode = exitErr.ExitCode()
102→	}
103→
104→	return Output{
105→		Command:  "claude " + strings.Join(displayArgs, " "),
106→		Stdout:   stdout.String(),
107→		Stderr:   stderr.String(),
108→		ExitCode: exitCode,
109→	}, err
110→}
111→
112→func (c *Claude) StartSession(ctx context.Context, dir string) (Session, error) {
113→	name := fmt.Sprintf("claude-test-%d", time.Now().UnixNano())
114→	// Interactive sessions rely on macOS Keychain for auth, so we can't
115→	// override CLAUDE_CONFIG_DIR without triggering a login prompt. Prompt
116→	// hardening ("Do not use worktrees") covers interactive tests instead.
117→	s, err := NewTmuxSession(name, dir, []string{"CLAUDECODE"}, "env", "ACCESSIBLE=1", "ENTIRE_TEST_TTY=0", "claude", "--dangerously-skip-permissions")
118→	if err != nil {
119→		return nil, err
120→	}
121→
122→	// Dismiss startup dialogs until we reach the input prompt.
123→	for i := 0; i < 5; i++ {
124→		content, err := s.WaitFor(`❯`, 15*time.Second)
125→		if err != nil {
126→			return s, fmt.Errorf("waiting for startup prompt: %w", err)
127→		}
128→		if !strings.Contains(content, "Enter to confirm") {
129→			break
130→		}
131→		// The bypass permissions dialog defaults to "No, exit" —
132→		// arrow down to "Yes, I accept" before confirming.
133→		if strings.Contains(content, "Yes, I accept") {
134→			_ = s.SendKeys("Down")
135→			time.Sleep(200 * time.Millisecond)
136→		}
137→		_ = s.SendKeys("Enter")
138→		time.Sleep(500 * time.Millisecond)
139→	}
140→	s.stableAtSend = ""
141→
142→	return s, nil
143→}
