 37→func (a *openCodeAgent) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 38→	cfg := &runConfig{}
 39→	for _, o := range opts {
 40→		o(cfg)
 41→	}
 42→
 43→	model := a.model
 44→	if cfg.Model != "" {
 45→		model = cfg.Model
 46→	}
 47→
 48→	args := []string{"run"}
 49→	if model != "" {
 50→		args = append(args, "--model", model)
 51→	}
 52→	args = append(args, prompt)
 53→
 54→	timeout := a.timeout
 55→	if envTimeout := os.Getenv("E2E_TIMEOUT"); envTimeout != "" {
 56→		if parsed, err := time.ParseDuration(envTimeout); err == nil {
 57→			timeout = parsed
 58→		}
 59→	}
 60→
 61→	ctx, cancel := context.WithTimeout(ctx, timeout)
 62→	defer cancel()
 63→
 64→	cmd := exec.CommandContext(ctx, "opencode", args...)
 65→	cmd.Dir = dir
 66→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
 67→
 68→	var stdout, stderr strings.Builder
 69→	cmd.Stdout = &stdout
 70→	cmd.Stderr = &stderr
 71→
 72→	err := cmd.Run()
 73→	out := Output{
 74→		Command: fmt.Sprintf("opencode %s", strings.Join(args, " ")),
 75→		Stdout:  stdout.String(),
 76→		Stderr:  stderr.String(),
 77→	}
 78→
 79→	if err != nil {
 80→		var exitErr *exec.ExitError
 81→		if errors.As(err, &exitErr) {
 82→			out.ExitCode = exitErr.ExitCode()
 83→		} else {
 84→			out.ExitCode = -1
 85→		}
 86→		return out, err
 87→	}
 88→
 89→	return out, nil
 90→}
